kspace{padding:22px 0;gap:5vw}.character-card{height:108px}.fighter-info{padding:13px 0;min-height:125px}.weapons-heading{margin-top:14px}.left-col h1{font-size:42px}.intro{margin-bottom:18px}.mode{padding:12px 8px}.rules{margin:20px 0 15px}.top{padding:15px 0}footer{padding:13px 0}.arena-card{height:86px}}@media(max-width:760px){.workspace{grid-template-columns:1fr;gap:30px}.left-col h1{font-size:38px}.selection{padding-bottom:20px}.desktop-tag{display:none}.fighter-info{grid-template-columns:1fr 1fr}.arena-grid{grid-template-columns:repeat(2,1fr)}.header-right{gap:8px}.build{font-size:8px}.character-card{height:125px}.combat-help{display:none}.fighter-hud{min-width:130px;padding:9px}.match-top{padding:12px}#fightersHud{gap:5px;bottom:10px;width:97%}.help-controls{grid-template-columns:1fr}}

