function fighter(c,p,time,front=false){const a=p.attack;if(!a)return;const stage=a.heavy?F.activeStage(a):null,pose=F.pose(p,time),color=a.context==='air'?'#d3eaf4':F.char(p.character).color,w=F.weapon(p.weapon),age=a.age,progress=stage?F.clamp((age-stage.start)/stage.duration,0,1):F.clamp(age/a.duration,0,1),active=a.heavy&&stage&&!['windup','recover'].includes(stage.role),power=stage?.role==='finisher'?1.45:1;
