 if(!active){if(a.heavy&&stage?.role==='windup'){c.save();const size=5+progress*10,x=p.x+p.facing*pose.hand.x,y=p.y+pose.hand.y;glow(c,x,y,size*2,color+'44');if(a.context!=='air'&&p.character==='bastion')rock(c,x,y,size*.45,time*3);else if(a.context!=='air'&&p.character==='ember')flame(c,x,y+5,size*.55,time);c.restore();}return;}c.save();c.translate(p.x,p.y-40);c.scale(p.facing||1,1);const strength=Math.sin(progress*Math.PI)*power;c.globalAlpha=.48+strength*.27;if(a.aim==='up')c.rotate(-Math.PI/2);else if(a.aim==='down')c.rotate(Math.PI/2);const envelope=.65+Math.sin(progress*Math.PI)*.35;c.scale(envelope,envelope);
