function resetInput(){keys.clear();lightHeld=false;chargeHeld=false;heavyUntil=0;latches={jump:0,dodge:0,interact:0};if(socket?.readyState===1&&playing)socket.send(JSON.stringify({type:'input',input:{}}));}
function input(now){return {left:keys.has('KeyA'),right:keys.has('KeyD'),up:keys.has('KeyW'),down:keys.has('KeyS'),jump:keys.has('Space')||latches.jump>now,dodge:keys.has('ShiftLeft')||keys.has('ShiftRight')||latches.dodge>now,light:lightHeld,heavy:chargeHeld||heavyUntil>now,interact:keys.has('KeyE')||latches.interact>now};}
