function updateHUD(){const remaining=Math.max(0,Math.ceil(state.duration-state.time));$('timer').textContent=Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0');$('connection').textContent=networkState?'LIVE · '+ping+' ms':'LOCAL · NO CONNECTION NEEDED';for(const p of state.players){const el=$('hud-'+p.id);if(!el)continue;el.classList.toggle('out',p.eliminated);el.querySelector('.damage').textContent=p.eliminated?'OUT':Math.round(p.damage)+'%';el.querySelector('.damage').style.color=p.damage>120?'#ff9a7e':p.damage>70?'#e7c68e':'#fff8de';el.querySelector('.weapon-name').textContent=F.weapon(p.weapon).name;el.querySelector('.technique').textContent=p.attack?.heavy?p.attack.name:p.charging?'Charging signature…':p.weapon==='unarmed'?'E · Find a mystery pickup':'';[...el.querySelector('.stocks').children].forEach((pip,i)=>pip.classList.toggle('lost',i>=p.stocks));el.querySelector('.dodge-bar').style.width=Math.round((1-p.dodgeCD/(p.character==='lyra'?1.05:1.45))*100)+'%';}}
