function processEvents(){for(const e of state.events){if(e.id<=lastEvent)continue;lastEvent=e.id;audioEvent(e);window.CombatFX?.notify(e);if(e.type==='hit'){shake=Math.max(shake,e.heavy?8:3);for(let j=0;j<(e.heavy?20:10);j++){const a=Math.random()*Math.PI*2;particles.push({x:e.x,y:e.y,vx:Math.cos(a)*(80+Math.random()*220),vy:Math.sin(a)*(80+Math.random()*220),life:.2+Math.random()*.25,color:F.char(state.players.find(p=>p.id===e.source)?.character).color});}}if(e.type==='start')announce('FIGHT',800);if(e.type==='ko')shake=16;}if(state.phase==='countdown')$('callout').textContent=String(Math.max(1,Math.ceil(state.countdown)));else if(performance.now()>calloutUntil)$('callout').textContent='';}
function endScreen(){if(!$('results').hidden)return;resetInput();modal('pause',false);const winner=state.players.find(p=>p.id===state.winner);$('winner').textContent=winner?winner.id===localId?'Your moment. Your victory.':winner.name+' takes the arena.':'A hard-fought draw.';$('resultInfo').textContent=F.maps[state.map].name+' · '+Math.floor(state.time/60)+':'+String(Math.floor(state.time%60)).padStart(2,'0')+' · '+(networkState?'Online match':'Bot match');$('scoreboard').replaceChildren();const sorted=[...state.players].sort((a,b)=>b.stocks-a.stocks||a.damage-b.damage||b.kos-a.kos);for(const [i,p]of sorted.entries()){const row=document.createElement('div');row.className='score-row';for(const value of [String(i+1),p.name,p.kos+' KOs',Math.round(p.dealt)+' damage']){const el=document.createElement('span');el.textContent=value;row.append(el);}const small=document.createElement('small');small.textContent=F.char(p.character).name+' / '+F.weapon(p.weapon).name;row.children[1].append(small);$('scoreboard').append(row);}modal('results',true);}
function startBots(){const size=Number($('format').value),players=[{id:'you',name:$('name').value.trim()||'You',character}];for(let i=1;i<size;i++)players.push({id:'bot'+i,name:'Rival '+i,bot:true,character:'random'});enterMatch(F.create({map:mapId,seed:Date.now()%2147483647,players,botLevel:Number($('botLevel').value),countdown:3}),'you',false);}
function send(m){if(socket?.readyState===1){socket.send(JSON.stringify(m));return true;}return false;}
function joinOnline(){if(!['http:','https:'].includes(location.protocol)){setStatus('Online play needs the included Node server. Open the hosted game link or follow README.md.');return;}queueing=true;modal('queue',true);$('queueText').textContent='Connecting to the game server…';const ws=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/play');socket=ws;const timeout=setTimeout(()=>{if(socket===ws&&queueing){ws.close();socket=null;queueing=false;modal('queue',false);setStatus('Could not reach the game server. Please try again.');}},12000);ws.onopen=()=>{if(socket!==ws)return;clearTimeout(timeout);send({type:'queue',version:F.VERSION,name:$('name').value.trim()||'Fighter',character,map:mapId,size:Number($('format').value)});};ws.onmessage=e=>{if(socket!==ws)return;let m;try{m=JSON.parse(e.data);}catch{return;}if(m.type==='welcome')localId=m.id;if(m.type==='queued')$('queueText').textContent=m.count+' / '+m.size+' fighters ready · Waiting for '+Math.max(0,m.size-m.count)+' more.';if(m.type==='matched'){clearTimeout(timeout);enterMatch(m.state,m.id,true);announce('MATCH FOUND',1000);}if(m.type==='state'){const own=m.state.players.find(p=>p.id===localId),old=predictedPlayer;state=m.state;networkState=m.state;snapshotAt=performance.now();if(own){pendingCommands=pendingCommands.filter(q=>q.seq>(own.inputAck||0));predictedPlayer=clone(own);if(!old||old.stocks!==own.stocks||own.respawn>0||own.eliminated){pendingCommands=[];correction={x:0,y:0};}else{for(const cmd of pendingCommands)F.predictPlayer(state,predictedPlayer,cmd.input);const dx=old.x-predictedPlayer.x,dy=old.y-predictedPlayer.y;correction=Math.hypot(dx,dy)<150?{x:dx,y:dy}:{x:0,y:0};}previousPrediction=clone(predictedPlayer);}}if(m.type==='pong')ping=Math.max(0,Math.round(performance.now()-m.at));if(m.type==='error'){cancelSearch();setStatus(m.message);}if(m.type==='notice')announce(m.message,1500);};ws.onclose=()=>{clearTimeout(timeout);if(socket!==ws)return;socket=null;if(queueing){queueing=false;modal('queue',false);setStatus('Disconnected from matchmaking. Please try again.');}else if(playing&&networkState&&!state?.ended){returnToSetup();setStatus('Connection lost. The server ended your participation in that match.');}};ws.onerror=()=>{};}
