 const displayPlayers=[];for(const authoritative of state.players){const p=networkState&&authoritative.id===localId&&predictedPlayer?predictedPlayer:authoritative;if(p.eliminated||p.respawn>0)continue;let v=viewPlayers.get(p.id),target={...p},alpha=F.clamp(acc/F.DT,0,1);if(!networkState){const old=previousLocalFrame.get(p.id)||p;v={x:old.x+(p.x-old.x)*alpha,y:old.y+(p.y-old.y)*alpha};target.runPhase=(old.runPhase||0)+((p.runPhase||0)-(old.runPhase||0))*alpha;}else if(p.id===localId){const old=previousPrediction||p;correction.x*=Math.exp(-dt*22);correction.y*=Math.exp(-dt*22);v={x:old.x+(p.x-old.x)*alpha+correction.x,y:old.y+(p.y-old.y)*alpha+correction.y};}else{const elapsed=Math.min(.07,(now-snapshotAt)/1000),tx=p.x+p.vx*elapsed,ty=p.y+(p.grounded?0:p.vy*elapsed);if(!v||Math.abs(v.x-p.x)>220||Math.abs(v.y-p.y)>260)v={x:p.x,y:p.y};else{const k=1-Math.exp(-dt*35);v.x+=(tx-v.x)*k;v.y+=(ty-v.y)*k;}target.runPhase=(p.runPhase||0)+Math.abs(p.vx)/150*elapsed;if(p.attack)target.attack={...p.attack,age:Math.min(p.attack.duration-.001,p.attack.age+elapsed)};}viewPlayers.set(p.id,v);target.x=v.x;target.y=v.y;
if(target.attack&&!networkState)target.attack={...target.attack,age:Math.min(target.attack.duration-.001,target.attack.age+acc)};displayPlayers.push(target);}
 window.PaintedSprites?.beginFrame(displayPlayers,now/1000);for(const target of displayPlayers){const p=target,v=target;window.CombatFX?.fighter(ctx,target,now/1000,false);A.fighter(ctx,target,now/1000);window.CombatFX?.fighter(ctx,target,now/1000,true);ctx.textAlign='center';ctx.font=(p.id===localId?'600 ':'')+'12px system-ui';const label=p.name+(p.id===localId?' · YOU':'');ctx.fillStyle='#0a182e77';const width=ctx.measureText(label).width+18;ctx.beginPath();ctx.roundRect(v.x-width/2,v.y-143,width,23,4);ctx.fill();ctx.fillStyle=F.char(p.character).color;ctx.fillText(label,v.x,v.y-127);if(p.id===localId){ctx.beginPath();ctx.moveTo(v.x-4,v.y-119);ctx.lineTo(v.x+4,v.y-119);ctx.lineTo(v.x,v.y-114);ctx.fill();}if(p.charging){ctx.fillStyle='#0d1a2399';ctx.fillRect(v.x-20,v.y-154,40,3);ctx.fillStyle=F.char(p.character).color;ctx.fillRect(v.x-20,v.y-154,40*p.charge,3);}if(p.y<0){ctx.fillStyle=F.char(p.character).color;ctx.beginPath();ctx.arc(p.x,24,14,0,Math.PI*2);ctx.fill();}}
 for(const q of state.shots){if(!(q.delay>0)&&window.CombatFX?.projectile(ctx,q,now/1000))continue;if(q.delay>0){ctx.globalAlpha=.25;A.glow(ctx,q.x,q.y,q.r,q.color+'66');ctx.globalAlpha=1;continue;}ctx.save();ctx.translate(q.x,q.y);if(q.kind==='bow'){ctx.rotate(Math.atan2(q.vy,q.vx));A.line(ctx,-20,0,10,0,'#dcd9b5',2);A.line(ctx,4,-4,12,0,q.color,2);A.line(ctx,4,4,12,0,q.color,2);}else if(q.kind==='ring'){ctx.rotate(now*.015);ctx.strokeStyle=q.color;ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(0,0,16,7,0,0,Math.PI*2);ctx.stroke();}else if(['tremor','wave','vortex','wind','flame','pillar','echo'].includes(q.kind)){ctx.strokeStyle=q.color;ctx.lineWidth=3;ctx.beginPath();if(q.kind==='pillar'){ctx.moveTo(-15,20);ctx.quadraticCurveTo(-26,-22,0,-65);ctx.quadraticCurveTo(26,-22,15,20);}else if(q.kind==='echo'){A.weapon(ctx,q.skin,-25,0,now*.005,.6,q.color);}else{ctx.ellipse(0,0,q.r,q.r*(q.kind==='wave'?1.3:.6),now*.004,0,Math.PI*1.65);}ctx.stroke();}else{A.glow(ctx,0,0,q.r*3,q.color+'55');A.ellipse(ctx,0,0,q.r,q.r,q.color);A.ellipse(ctx,-q.r*.25,-q.r*.25,q.r*.4,q.r*.4,'#fffce7b0');}ctx.restore();}
