function frame(now){const dt=Math.min(.1,Math.max(0,(now-last)/1000));last=now;frameTime=now;if(playing&&state){if(!state.ended){if(!networkState&&!paused){acc+=dt;let n=0;while(acc>=F.DT&&n++<6){for(const p of state.players)previousLocalFrame.set(p.id,{x:p.x,y:p.y,runPhase:p.runPhase});F.step(state,{[localId]:input(now)});acc-=F.DT;}}else if(networkState){acc+=dt;let n=0;while(acc>=F.DT&&n++<6){const command={seq:++commandSequence,input:paused?{}:input(now)};pendingCommands.push(command);if(pendingCommands.length>120)pendingCommands.shift();if(predictedPlayer){previousPrediction=clone(predictedPlayer);F.predictPlayer(state,predictedPlayer,command.input);}acc-=F.DT;}}}if(networkState){if(now-lastSent>25){send({type:'input',commands:pendingCommands.slice(-12)});lastSent=now;}if(now-lastPing>2000){send({type:'ping',at:now});lastPing=now;}}processEvents();updateHUD();if(state.ended)endScreen();}render(now,dt);requestAnimationFrame(frame);}
