'use strict';
window.MoveLab=(()=>{const F=window.Fight,A=window.Art,$=id=>document.getElementById(id);let state=null,actor=null,dummy=null,raf=null,last=0,acc=0,elapsed=0,forced=false,camera={x:680,y:550},ready=false;
 function build(){if(ready)return;ready=true;for(const c of F.characters){const o=document.createElement('option');o.value=c.id;o.textContent=c.name;$('labFighter').append(o);}for(const w of [F.UNARMED,...F.weapons]){const o=document.createElement('option');o.value=w.id;o.textContent=w.name;$('labWeapon').append(o);}for(const id of ['labFighter','labWeapon','labContext','labAim','labHit'])$(id).onchange=reset;$('labReplay').onclick=reset;$('closeLab').onclick=close;$('labSpeed').value='1';$('labAim').value='side';$('labContext').value='ground';$('labHit').checked=true;}
 function reset(){const context=$('labContext').value,aim=$('labAim').value;state=F.create({map:0,duration:999,players:[{id:'lab',character:$('labFighter').value},{id:'target',character:'bastion'}]});[actor,dummy]=state.players;Object.assign(actor,{x:620,y:context==='air'||context==='cancel'?460:650,weapon:$('labWeapon').value,grounded:context!=='air'&&context!=='cancel',invuln:0});Object.assign(dummy,{x:695,y:actor.y,invuln:999,grounded:true});if(context==='cancel'){actor.airDodgeWindow=.2;F.gravityCancel(state,actor);}F.strike(state,actor,context!=='light',.4,{up:aim==='up',down:aim==='down'});$('labHit').disabled=context==='air'||context==='light';elapsed=acc=0;forced=false;camera={x:660,y:actor.y-65};window.CombatFX?.reset();$('labMove').textContent=actor.attack?.name||F.weapon(actor.weapon).name+' · light chain';$('labNote').textContent=(context==='air'?'Aerial heavies are identical for every fighter holding this weapon. ':context==='cancel'?'This uses the same character-specific ground signature from a temporary ghost platform. ':'')+'Animation preview with a simulated opener result; gameplay still requires an actual hit.';}
 function open(character='lyra',weapon='sabre'){build();$('moveLab').hidden=false;$('labFighter').value=character;$('labWeapon').value=weapon;reset();last=performance.now();if(raf==null)raf=requestAnimationFrame(frame);}
 function close(){$('moveLab').hidden=true;if(raf!=null)window.cancelAnimationFrame?.(raf);raf=null;state=null;}
 function frame(now){raf=null;if($('moveLab').hidden||!state)return;const dt=Math.min(.05,(now-last)/1000);last=now;acc+=dt*Number($('labSpeed').value||1);while(acc>=F.DT){elapsed+=F.DT;if($('labContext').value==='light'&&!actor.attack&&actor.attackCD<=0)F.strike(state,actor,false,0,{up:$('labAim').value==='up',down:$('labAim').value==='down'});const a=actor.attack,st=F.activeStage(a);if(a?.heavy&&a.context!=='air'&&st?.role==='opener'&&!forced&&(a.age-st.start)/st.duration>.23&&$('labHit').checked){forced=true;dummy.invuln=0;dummy.x=actor.x+actor.facing*38;dummy.y=actor.y-10;F.confirmAttack(state,actor,a,dummy);}if(!$('labHit').checked)dummy.invuln=999;F.step(state,{});for(const e of state.events)if(e.type==='finisher'&&!e.labSeen){e.labSeen=true;window.CombatFX?.notify(e);}if(elapsed>2.2||actor.eliminated)reset();acc-=F.DT;}
 const cv=$('labCanvas'),c=cv.getContext('2d'),zoom=Math.min(cv.width/565,cv.height/315);camera.x+=(actor.x+25-camera.x)*Math.min(1,dt*4);camera.y+=(actor.y-65-camera.y)*Math.min(1,dt*5);c.setTransform(1,0,0,1,0,0);c.fillStyle='#14232e';c.fillRect(0,0,cv.width,cv.height);c.save();c.translate(cv.width/2-camera.x*zoom,cv.height/2-camera.y*zoom);c.scale(zoom,zoom);A.scene(c,F.maps[0],now/1000,true);window.CombatFX?.platform(c,actor,elapsed);window.PaintedSprites?.beginFrame([{...dummy,invuln:0},{...actor,invuln:0}],elapsed);for(const p of [dummy,actor]){window.CombatFX?.fighter(c,p,elapsed,false);A.fighter(c,{...p,invuln:0},elapsed);window.CombatFX?.fighter(c,p,elapsed,true);}for(const q of state.shots){if(q.delay>0)continue;if(!window.CombatFX?.projectile(c,q,elapsed)){A.glow(c,q.x,q.y,q.r*2,q.color+'77');A.ellipse(c,q.x,q.y,q.r,q.r,q.color);}}window.CombatFX?.impacts(c,dt,elapsed);c.restore();const stage=F.activeStage(actor.attack);$('labPhase').textContent=actor.attack?.heavy?(stage?.role||'recovery').toUpperCase()+(actor.attack.confirmed?' · CONFIRMED':actor.attack.missed?' · MISS BRANCH':''):'LIGHT ATTACK';raf=requestAnimationFrame(frame);}
 return {open,close};})();

