'use strict';
(()=>{
 const summary=document.getElementById('artCheckSummary'),details=document.getElementById('artCheckDetails'),retry=document.getElementById('artCheckRetry');if(!summary||!details||!retry)return;
 async function check(reload=false){if(reload)window.PaintedSprites?.retry();if(typeof fetch!=='function'||location.protocol==='file:'){summary.textContent='Character folders load beside the game folder.';details.textContent='For the complete upload check, open the hosted game and click CHECK FOLDERS.';return;}retry.disabled=true;summary.textContent='Checking character folders…';try{const response=await fetch('./graphics-status',{cache:'no-store'});if(!response.ok)throw Error('status');const s=await response.json();summary.textContent=s.ready?'All character folders are ready · 45/45 images':'Character images found: '+s.found+'/45';details.textContent=s.characters.map(c=>c.name+' '+c.found+'/9').join(' · ')+(s.ready?'':'. Missing or invalid: '+s.missing.slice(0,5).join(', ')+(s.missing.length>5?'…':''));summary.parentElement?.parentElement?.classList?.toggle('ready',s.ready);}catch{summary.textContent='The character folder check could not reach this server.';details.textContent='Deploy the main game files, then open /graphics-status to check the installed version.';}finally{retry.disabled=false;}}
 retry.onclick=()=>check(true);check();
})();
